import{_ as e,c as l,o as r,ag as n}from"./chunks/framework.BSxiluPM.js";const x=JSON.parse('{"title":"청년도약계좌와 청년미래적금","description":"","frontmatter":{"title":"청년도약계좌와 청년미래적금","date":"2026-01-20T00:00+09:00"},"headers":[],"relativePath":"posts/youth-savings.md","filePath":"posts/youth-savings.md","lastUpdated":1770127740000}'),s={name:"posts/youth-savings.md"};function o(a,t,i,g,d,h){return r(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="청년도약계좌와-청년미래적금" tabindex="-1">청년도약계좌와 청년미래적금 <a class="header-anchor" href="#청년도약계좌와-청년미래적금" aria-label="Permalink to &quot;청년도약계좌와 청년미래적금&quot;">​</a></h1><p>청년들의 자산 형성을 돕기 위한 대표적인 정책 금융 상품으로 <strong>2026년 6월 청년미래적금이 출시될 예정</strong>입니다. 기존 청년도약계좌와는 가입 기간, 정부 지원 방식, 소득 요건 등에서 큰 차이가 있습니다.</p><h2 id="_1-청년도약계좌-현행" tabindex="-1">1. 청년도약계좌 (현행) <a class="header-anchor" href="#_1-청년도약계좌-현행" aria-label="Permalink to &quot;1. 청년도약계좌 (현행)&quot;">​</a></h2><p>5년이라는 <strong>장기적인 관점</strong>에서 꾸준히 저축하여 목돈을 마련하도록 설계된 상품</p><ul><li><strong>가입 기간:</strong> 5년 (만기 시까지 유지 필요)</li><li><strong>월 납입 한도:</strong> 최대 70만 원</li><li><strong>정부 기여금:</strong> 월 납입액의 3~6% (월 최대 3.3만 원)</li><li><strong>가입 종료:</strong> <strong>2025년 12월 31일</strong> (이후 신규 가입 불가)</li><li><strong>소득 요건:</strong><ul><li>개인소득: 연 7,500만 원 이하</li><li>가구소득: 기준 중위소득 250% 이하 (2025년 완화된 기준)</li></ul></li></ul><h2 id="_2-청년미래적금-신설-예정" tabindex="-1">2. 청년미래적금 (신설 예정) <a class="header-anchor" href="#_2-청년미래적금-신설-예정" aria-label="Permalink to &quot;2. 청년미래적금 (신설 예정)&quot;">​</a></h2><p>청년도약계좌의 긴 만기 부담을 줄이고, 혜택을 강화하여 2026년 6월 출시 예정인 후속 상품</p><ul><li><strong>출시 예정:</strong> <strong>2026년 6월</strong></li><li><strong>가입 기간:</strong> <strong>3년</strong> (부담 완화)</li><li><strong>월 납입 한도:</strong> 최대 50만 원</li><li><strong>정부 기여금:</strong><ul><li><strong>일반형:</strong> 납입액의 <strong>6%</strong> 매칭</li><li><strong>우대형:</strong> 납입액의 <strong>12%</strong> 매칭 (소득 및 우대 조건 충족 시)</li></ul></li><li><strong>가입 연령 특례:</strong> 2026년 출시 시점에 만 34세를 초과하더라도, <strong>2025년 기준 만 34세</strong>였다면 가입이 가능하도록 예외를 둡니다. 또한, <strong>병역 이행자의 경우 최대 만 40세까지</strong> 가입이 가능</li><li><strong>소득 요건:</strong><ul><li>개인소득: 연 6,000만 원 이하</li><li>가구소득: 기준 중위소득 200% 이하 <blockquote><p><strong>[참고] 2026년 기준 중위소득 (월 소득 환산)</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">가구원 수</th><th style="text-align:center;">100%</th><th style="text-align:center;">150% (우대형 조건 등)</th><th style="text-align:center;">200% (가입 상한)</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1인</strong></td><td style="text-align:center;">2,564,238원</td><td style="text-align:center;">3,846,357원</td><td style="text-align:center;">5,128,476원</td></tr><tr><td style="text-align:center;"><strong>2인</strong></td><td style="text-align:center;">4,199,293원</td><td style="text-align:center;">6,298,940원</td><td style="text-align:center;">8,398,586원</td></tr><tr><td style="text-align:center;"><strong>3인</strong></td><td style="text-align:center;">5,359,036원</td><td style="text-align:center;">8,038,554원</td><td style="text-align:center;">10,718,072원</td></tr><tr><td style="text-align:center;"><strong>4인</strong></td><td style="text-align:center;">6,494,738원</td><td style="text-align:center;">9,742,107원</td><td style="text-align:center;">12,989,476원</td></tr></tbody></table></blockquote></li></ul></li></ul><h2 id="_3-핵심-비교-요약" tabindex="-1">3. 핵심 비교 요약 <a class="header-anchor" href="#_3-핵심-비교-요약" aria-label="Permalink to &quot;3. 핵심 비교 요약&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">구분</th><th style="text-align:left;">청년도약계좌 (현행)</th><th style="text-align:left;">청년미래적금 (신설 예정)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>만기</strong></td><td style="text-align:left;">5년</td><td style="text-align:left;"><strong>3년</strong></td></tr><tr><td style="text-align:left;"><strong>월 납입 한도</strong></td><td style="text-align:left;">70만 원</td><td style="text-align:left;">50만 원</td></tr><tr><td style="text-align:left;"><strong>정부 기여금</strong></td><td style="text-align:left;">3~6% (최대 3.3만 원)</td><td style="text-align:left;"><strong>6% ~ 12%</strong></td></tr><tr><td style="text-align:left;"><strong>최대 혜택 예시</strong></td><td style="text-align:left;">5년 납입 시 약 5,000만 원 목돈 마련</td><td style="text-align:left;">3년 납입 시 높은 수익률 + 유동성 확보</td></tr><tr><td style="text-align:left;"><strong>신규 가입</strong></td><td style="text-align:left;"><strong>2025년 말 종료</strong></td><td style="text-align:left;"><strong>2026년 6월 개시</strong></td></tr></tbody></table><h2 id="_4-청년미래적금-왜-주목해야-할까" tabindex="-1">4. 청년미래적금, 왜 주목해야 할까? <a class="header-anchor" href="#_4-청년미래적금-왜-주목해야-할까" aria-label="Permalink to &quot;4. 청년미래적금, 왜 주목해야 할까?&quot;">​</a></h2><p><strong>&quot;짧고 굵게, 효율적으로 모으고 싶다.&quot;</strong></p><ul><li>결혼, 주거 마련 등 3~4년 내에 목돈이 필요하다면 3년 만기인 청년미래적금이 좋은 선택입니다.</li><li><strong>가입 연령 막차:</strong> 2025년에 만 34세가 된 분들도 2026년 출시에 맞춰 최대 40세까지 가입할 수 있습니다.</li><li>우대형 조건(중소기업 재직, 소득 요건 등)에 해당하여 <strong>12%의 정부 기여금</strong>을 받을 수 있다면 수익률 측면에서 유리합니다.</li><li><strong>납입금액 무관:</strong> 납입금액에 상관없이 정해진 비율(6% 또는 12%)로 정부 기여금이 지급됩니다.</li></ul><h2 id="_5-실제-적용-예시" tabindex="-1">5. 실제 적용 예시 <a class="header-anchor" href="#_5-실제-적용-예시" aria-label="Permalink to &quot;5. 실제 적용 예시&quot;">​</a></h2><p>저와 여자친구의 상황을 대입해보면 다음과 같이 결정을 내릴 수 있습니다.</p><ul><li><p><strong>저의 경우 (청년도약계좌 가입 중, 만기 2030년 3월):</strong></p><ul><li><strong>선택:</strong> <strong>청년도약계좌 유지</strong></li><li><strong>이유:</strong> 이미 청년도약계좌에 가입하여 2030년 3월 만기를 목표로 납입하고 있습니다. 본래 장기 저축을 통한 목돈 마련을 위해 유지하려고 합니다. 청년도약계좌에 납입하는 금액 이외에는 ISA 계좌에 투자하고 있어요.</li></ul></li><li><p><strong>여자친구의 경우 (중소기업 재직, 연소득 3,600만 원 이하):</strong></p><ul><li><strong>선택:</strong> <strong>청년미래적금 (우대형)</strong></li><li><strong>이유:</strong> 중소기업 우대 조건과 소득 요건을 모두 충족하므로, 높은 정부 기여금을 받을 수 있습니다. <strong>청년도약계좌에 납입한 금액이 적어서</strong>, 부담이 적은 청년미래적금으로 전환하는 것이 유리합니다. 2026년 6월에 가입하면 <strong>만기는 2029년 6월</strong>로, 저의 청년도약계좌 만기(2030년 3월)보다 약 9개월 먼저 목돈을 마련할 수 있습니다.</li></ul></li></ul><h2 id="마치며" tabindex="-1">마치며 <a class="header-anchor" href="#마치며" aria-label="Permalink to &quot;마치며&quot;">​</a></h2><p>저희처럼 2026년 혼인을 앞두고 있다면, 청년도약계좌를 혼인 사유로 특별해지하는 것을 고민하기보다, 3년 만기로 자금 회전이 빠른 <strong>청년미래적금으로 전환</strong>하는 것이 좋은 선택 같습니다.</p><h4 id="참고-기사" tabindex="-1">참고 기사 <a class="header-anchor" href="#참고-기사" aria-label="Permalink to &quot;참고 기사&quot;">​</a></h4><ul><li><a href="https://www.koreaeaglenews.com/news/articleView.html?idxno=95018" target="_blank" rel="noreferrer">청년미래적금 &#39;34세&#39; 넘어도 한 차례 기회 제공…2026년 6월 출시</a></li><li><a href="https://www.ytn.co.kr/_ln/0102_202601161424395486" target="_blank" rel="noreferrer">청년미래적금 최대 40세까지 가입 가능</a></li><li><a href="https://kbthink.com/investment/issues/2026-policy-changes.html" target="_blank" rel="noreferrer">2026년 달라지는 제도 | 최저시급부터 청년미래적금까지 총정리</a></li></ul>',20)])])}const u=e(s,[["render",o]]);export{x as __pageData,u as default};
